import assert from 'node:assert/strict'
import { readFileSync, writeFileSync } from 'node:fs'
import { createHash } from 'node:crypto'
import { fingerprintSemanticKindSourceGoal, parseSemanticKindLedger } from '../app/scripts/goalBookModel.ts'

const sourcePath = 'curricula/DE/Gymnasium/canonical/DE_DEU_S_GYM_CANONICAL_MATHEMATIK.de.json'
const ledgerPath = 'curricula/DE/Gymnasium/quality/release-model/mathematik.semantic-kinds.json'
const proposalPath = 'docs/dev/ci-graph-repairs/math-memory-prerequisites-repair-proposal-2026-11-06.json'
const read = (p: string) => JSON.parse(readFileSync(p, 'utf8'))
const digest = (b: Buffer | string) => createHash('sha256').update(b).digest('hex')
const binding = (path: string) => ({ path, sha256: digest(readFileSync(path)) })
const original = read(sourcePath), ledger = read(ledgerPath), proposal = read(proposalPath)
assert.equal(digest(readFileSync(sourcePath)), proposal.source.sha256)
for (const pinned of proposal.sourceVersions.filter((x: any) => x.path.includes('memory-'))) {
  assert.equal(digest(readFileSync(pinned.path)), pinned.sha256)
}
const after = structuredClone(original)
const changes = new Set<string>()
for (const op of proposal.operations) {
  const [, , index, field] = op.path.split('/')
  const goal = after.goals[Number(index)]
  assert.equal(op.operation, 'replace')
  assert.equal(field, 'requires')
  assert.equal(goal.id, op.guardGoalId)
  assert.deepEqual(goal.requires, op.guardRequiresBefore)
  goal.requires = structuredClone(op.value)
  changes.add(goal.id)
}
assert.equal(changes.size, 4)
assert.equal(proposal.operations.length, 5)
const successor = structuredClone(ledger)
const rows = [...changes].map(id => {
  const beforeGoal = original.goals.find((g: any) => g.id === id)
  const afterGoal = after.goals.find((g: any) => g.id === id)
  assert.deepEqual({ ...beforeGoal, requires: undefined }, { ...afterGoal, requires: undefined })
  assert.equal(afterGoal.nodeKind, 'memory')
  assert.deepEqual(afterGoal.contains, [])
  assert.equal(Object.hasOwn(afterGoal, 'examData'), false)
  const index = ledger.decisions.findIndex((d: any) => d.goalId === id)
  const old = ledger.decisions[index]
  assert.equal(old.semanticKind, 'memory')
  assert.equal(old.decisionBasis, 'reviewed-current-pilot-memory')
  assert.equal(old.sourceFingerprint, fingerprintSemanticKindSourceGoal(beforeGoal))
  const fresh = { ...old, sourceFingerprint: fingerprintSemanticKindSourceGoal(afterGoal) }
  assert.notEqual(old.sourceFingerprint, fresh.sourceFingerprint)
  successor.decisions[index] = fresh
  return { goalId: id, ledgerDecisionPointer: `/decisions/${index}`, originalGoal: beforeGoal,
    proposedGoal: afterGoal, oldDecision: old, proposedDecision: fresh }
})
const parse = (l: any, s: any) => parseSemanticKindLedger(l, s, original.landscapeId, sourcePath)
const checks: any[] = []
function pass(name: string, l: any, s: any) {
  const result = parse(l, s)
  checks.push({ name, outcome: 'accepted', decisionCount: result.semanticKindByGoalId.size })
}
function reject(name: string, l: any, s: any, diagnostic: RegExp) {
  let message: string | undefined
  try { parse(l, s) } catch (e) { message = String(e) }
  assert.ok(message, name)
  assert.match(message, diagnostic)
  checks.push({ name, outcome: 'rejected', diagnostic: message })
}
pass('original current1252 ledger and source', ledger, original)
reject('old decisions cannot carry forward to corrected candidate', ledger, after, /stale semantic-kind decision/)
pass('four independently reconsidered memory decisions in unchanged ledger form', successor, after)
for (const row of rows) {
  const onlyOneOld = structuredClone(successor)
  const i = onlyOneOld.decisions.findIndex((x: any) => x.goalId === row.goalId)
  onlyOneOld.decisions[i] = row.oldDecision
  reject(`old fingerprint individually rejected: ${row.goalId}`, onlyOneOld, after, /stale semantic-kind decision/)
}
const badMethod = { ...successor, reviewMethod: 'fresh-memory-recheck-v1' }
reject('invented reviewMethod forbidden', badMethod, after, /closed JSON Schema/)
const badBasis = structuredClone(successor)
badBasis.decisions.find((x: any) => x.goalId === rows[0].goalId).decisionBasis = 'reviewed-current-semantic-recheck-memory'
reject('invented decisionBasis forbidden', badBasis, after, /closed JSON Schema/)
const extraMetadata = structuredClone(successor)
extraMetadata.decisions.find((x: any) => x.goalId === rows[0].goalId).independentReview = 'not a schema field'
reject('review evidence must stay external to closed decision record', extraMetadata, after, /closed JSON Schema/)
const result = {
  status: 'hypothetical-kind-input-validation-no-application',
  bindings: [sourcePath, ledgerPath, proposalPath, 'app/scripts/goalBookModel.ts',
    'contracts/curriculum-package/v1/curriculum-ontology-profile.schema.json',
    'contracts/curriculum-package/v1/profiles/de-gymnasium-mathematik-v1.profile.json',
    'contracts/curriculum-package/v1/profiles/semantic-normal-form-v1.profile.json'].map(binding),
  operationCount: proposal.operations.length, changedGoalCount: rows.length,
  originalCounts: ledger.counts, successorCounts: successor.counts,
  rows, checks, sourceApplied: false, ledgerApplied: false, qaValidityClaimed: false,
}
for (const pin of result.bindings) assert.equal(digest(readFileSync(pin.path)), pin.sha256)
writeFileSync('tmp/math-memory-kind-native-check.json', JSON.stringify(result, null, 2) + '\n')
console.log(JSON.stringify({ checks: checks.length, rows: rows.length, decisions: ledger.decisions.length,
  sourceApplied: false, ledgerApplied: false, checksSummary: checks.map(x => ({ name: x.name, outcome: x.outcome })) }))
